const employment = ctx.subject.employment;
const terms = employment.terms;
const extension = get(employment, 'statutory_parameters', {});
const signed = get(employment, 'signed_contract_period', null);
const probation = get(terms, 'probation_period', null);
const ended = get(employment.effective_range, 'to', null);
if (ended != null && ended < ctx.run.salary_coverage.from) return false;
if (['CONTRACTOR', 'CONSULTANT', 'PAYEE', 'INTERN', 'APPRENTICE'].includes(employment.engagement))
	return false;
// Law 41/2024/QH15 art.2(1)(a): a probation clause in the labour contract is insured; only a separate probation contract is not.
if (
	probation != null &&
	ctx.run.salary_coverage.from <= probation.to &&
	get(extension, 'separate_probation_contract', false) === true
)
	return false;
if (get(extension, 'domestic_worker', false) === true) return false;
if (get(extension, 'receiving_pension', false) === true) return false;
if (get(extension, 'pass_type', '') === 'INTRA_COMPANY_TRANSFER') return false;

if (get(extension, 'statutory.HI.hi_treaty_exempt', false) === true) return false;

const foreign = !ctx.lookup.vietnamese_nationality.includes(
	String(get(employment, 'payroll.nationality', 'VN'))
);
const months =
	signed?.from == null || signed.to == null
		? Infinity
		: calendar_completed_months(signed.from, add_days(signed.to, 1));
if (
	months <
	(foreign ? ctx.lookup.foreign_minimum_contract_months : ctx.lookup.minimum_contract_months)
)
	return false;
const month = get(ctx.balances, 'month', {});
const paidMonth = String(ctx.run.pay_date).slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const isForeignAtRetirement = () => {
	if (!foreign) return false;
	const dob = get(employment, 'payroll.date_of_birth', null);
	if (dob == null || dob === '') return false;
	const signDate = get(employment, 'terms.signed_on', get(signed, 'from', employment.effective_range.from));
	const male = get(employment, 'payroll.gender', 'MALE') !== 'FEMALE';
	// Decree 135/2020 Annex I: normal retirement age rises +3m/yr (male 60y3m->62) or +4m/yr (female 55y4m->60) from 2021
	const yr = Number(String(signDate).slice(0, 4));
	const retMonths = male
		? Math.min(62 * 12, 60 * 12 + 3 + Math.max(0, yr - 2021) * 3)
		: Math.min(60 * 12, 55 * 12 + 4 + Math.max(0, yr - 2021) * 4);
	return calendar_completed_months(dob, signDate) >= retMonths;
};
// HI Law art.12(1)(c): foreign worker at statutory retirement age excluded
if (isForeignAtRetirement()) return false;
const review = get(extension, 'insurance_review', null);
const leaveEntries = get(ctx, 'leave', []);
const countLeaveDays = (codes) => sum(leaveEntries.filter((l) => codes.includes(l.catalog_code)).map((l) => Number(get(l, 'days', get(l, 'quantity', 0)))));
const maternityDays = countLeaveDays(['MATERNITY_LEAVE']);
const sickDays = countLeaveDays(['SICK_LEAVE']);
const unpaidDays = countLeaveDays(['NPL', 'STOPPAGE_WORKER_FAULT', 'BEREAVEMENT_LEAVE_UNPAID', 'SUSPENSION_PENDING_DISCIPLINE']) + maternityDays + sickDays;
const currentReview = get(review, 'month', '') === String(ctx.as_of).substring(0, 7) ? review : null;
// HI Law art.12(2)(b); Law 41/2024 art.84(2)(c): >=14 working days maternity or sickness transfers HI to SI fund
if (currentReview == null && (maternityDays >= 14 || sickDays >= 14)) return false;
const pay = Number(get(ctx.subtotals, 'PAID_BASIC', 0)) + before('PAID_BASIC');
if (currentReview == null && pay <= 0 && unpaidDays >= 14) return false;
return employment.engagement !== 'PART_TIME' || pay >= ctx.lookup.insurance_floor;

