// Law 41/2024/QH15 arts.13(2), 48(1)–(2), 62(1): Raises the task to obtain the SI benefit file and record its complete-file receipt date.
if (!ctx.lookup.benefit_catalogs.includes(ctx.entry.catalog_code)) return false;
return ctx.entry.evidence_file == null;

SI_BENEFIT_FILE_RECEIPT_REVIEW.effects:
// Law 41/2024/QH15 arts.13(2), 48(1)–(2), 62(1): Raises the task to obtain the SI benefit file and record its complete-file receipt date.
const last = ctx.reads.leave_catalog_entry_day.reduce((day, slot) => (slot.incurred_on > day ? slot.incurred_on : day), '');
const key = 'SI_BENEFIT_FILE_RECEIPT_REVIEW:' + ctx.entry.id;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
return [
	{
		entity_id: ctx.entry.entity_id,
		employment_id: ctx.entry.employment_id,
		title: ctx.lookup.title,
		due_on: last,
		occurrence_key: key
	}
];

FOREIGN_WORKER_NEW_DECREE_REVIEW.condition:
// Decree 393/2026/NĐ-CP, issued 20 October, effective 5 December 2026: Raises the onboarding task to record the actual work-authorisation route.
if (get(ctx.entry, 'terms.work_authorisation_category', null) != null) return false;
if (get(ctx.entry.statutory_parameters, 'pass_type', null) == null) return false;
return ctx.entry.effective_range.from >= ctx.lookup.commencement;

FOREIGN_WORKER_NEW_DECREE_REVIEW.effects:
// Decree 393/2026/NĐ-CP, issued 20 October, effective 5 December 2026: Raises the onboarding task to record the actual work-authorisation route.
const key = 'FOREIGN_WORKER_NEW_DECREE_REVIEW:' + ctx.entry.id;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
return [
	{
		entity_id: ctx.entry.entity_id,
		employee_id: ctx.entry.employee_id,
		employment_id: ctx.entry.id,
