const today = String(get(first(ctx.reads.payroll_run), 'pay_date', ''));
if (today < ctx.lookup.commencement) return false;
return get(ctx.subject.employment.statutory_parameters, 'pass_type', null) != null;

FOREIGN_WORKER_NEW_DECREE_TRANSITION.effects:
