const today = String(get(first(ctx.reads.payroll_run), 'pay_date', ''));
const key = 'FOREIGN_WORKER_NEW_DECREE_TRANSITION:' + ctx.entry.employment_id;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
