	}
];

WORK_PERMIT_TRANSITION_REVIEW.condition:
// Decree 219/2025/NĐ-CP arts.27(1), 28(1), 29 (in force 7 August s.27(1), 28(1), 29 (in force 7 August 2025), Official Gazette C: Raises the task to review the transitional work-authorisation deadline before 5 December 2026.
const today = String(get(first(ctx.reads.payroll_run), 'pay_date', ''));
if (ctx.subject.employment.effective_range.to == null) return false;
if (!(today < ctx.lookup.commencement)) return false;
if (!(today >= add_days(ctx.subject.employment.effective_range.to, -ctx.lookup.advance_days))) return false;
return get(ctx.subject.employment, 'terms.work_authorisation_category', null) != null;

WORK_PERMIT_TRANSITION_REVIEW.effects:
