WORK_PERMIT_RETURN_TRANSITION_REVIEW.condition:
// Decree 219/2025/NĐ-CP arts.30(1), 31(1): Raises the task to establish the transitional return deadline for a work authorisation.
if (ctx.after == null) return false;
if (get(ctx.entry.statutory_parameters, 'pass_type', null) == null) return false;
if (!(ctx.entry.effective_range.to < ctx.lookup.commencement)) return false;
return add_days(ctx.entry.effective_range.to, 15) >= ctx.lookup.commencement;

WORK_PERMIT_RETURN_TRANSITION_REVIEW.effects:
// pass_type records a foreign work-authorisation route; the contract carries no nationality.
const key = 'WORK_PERMIT_RETURN_TRANSITION_REVIEW:' + ctx.entry.id + ':exit:' + ctx.entry.effective_range.to;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
return [
	{
		entity_id: ctx.entry.entity_id,
		employee_id: ctx.entry.employee_id,
		employment_id: ctx.entry.id,
		title: ctx.lookup.title,
		due_on: add_days(ctx.entry.effective_range.to, 15),
		occurrence_key: key
	}
];

MINIMUM_WAGE_FLOOR.condition:
// Only the monthly wage of the job is checked; part-time, intern and probation terms are outside it.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate === null) return false;
if (rate.unit !== 'MONTHLY') return false;
if (!(rate.amount > 0)) return false;
if (['PART_TIME', 'INTERN'].includes(ctx.entry.engagement)) return false;
return get(ctx.entry, 'terms.probation_period', null) === null;

MINIMUM_WAGE_FLOOR.validate:
// Labour Code 45/2019/QH14 arts.90(2), 91: compliance validation.
const employer = ctx.subject.employer;
const region = get(employer, 'statutory_parameters.region', null);
const floor = get(ctx.lookup.minimum_wage.by_region, region, null);
return floor === null || ctx.entry.terms.rate.amount >= floor;

OVERTIME_MONTHLY_CAP.validate:
// Labour Code 45/2019/QH14 art.107(2)(b): compliance validation.
const from = month_start(ctx.entry.work_date);
const to = month_end(ctx.entry.work_date);
const siblings = ctx.reads.roster_entry.filter((day) => day.work_date >= from && day.work_date <= to && day.work_date !== ctx.entry.work_date);
const minutes =
	sum(siblings.map((day) => interval_minutes(day.planned_overtime_intervals ?? []))) +
	interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
return minutes / 60 <= ctx.lookup.overtime_hours;

OVERTIME_DAILY_CAP.validate:
// Labour Code 45/2019/QH14 art.107(2)(a): compliance validation.
const worked = interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []) / 60;
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []) / 60;
if (overtime === 0) return true;
const normal = worked - overtime;
return normal > 0 ? overtime <= ctx.lookup.share * normal : worked <= ctx.lookup.daily_hours;

DAMAGE_DEDUCTION_CEILING.condition:
// Labour Code 45/2019/QH14 art.102(3): Checks that a property-damage deduction does not exceed 30% of the latest payslip's net wage.
if (ctx.entry.catalog_code !== 'PROPERTY_DAMAGE_COMPENSATION') return false;
return true;

DAMAGE_DEDUCTION_CEILING.validate:
// Labour Code 45/2019/QH14 art.102(3): Checks that a property-damage deduction does not exceed 30% of the latest payslip's net wage.
const slip = ctx.reads.payslip.reduce(
	(last, row) => (last === null || String(row.period) > String(last.period) ? row : last),
	null
);
if (slip === null) return true;
const paid =
	get(slip, 'gross_earnings', 0) - get(slip, 'employee_statutory', 0) - get(slip, 'tax_withheld', 0);
return ctx.entry.quantity <= ctx.lookup.deduction_share * paid;

OVERTIME_ANNUAL_CAP.validate:
// Labour Code 45/2019/QH14 art.107(2)(b) s.61–62): compliance validation.
const year = ctx.entry.work_date.substring(0, 4);
const siblings = ctx.reads.roster_entry.filter(
	(day) => day.work_date.substring(0, 4) === year && day.work_date !== ctx.entry.work_date
);
const hours =
	(sum(siblings.map((day) => interval_minutes(day.planned_overtime_intervals ?? []))) +
		interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? [])) /
	60;
const employer = ctx.subject.employer;
const cap =
	get(employer, 'statutory_parameters.overtime_300h_sector', false) === true
		? ctx.lookup.extended_hours
		: ctx.lookup.ordinary_hours;
return hours <= cap;

REGION_REQUIRED.validate:
// Decree 74/2024/NĐ-CP arts.3–4: Requires the company's parameters on the contract start date to record a minimum-wage region.
const employer = ctx.subject.employer;
return ['I', 'II', 'III', 'IV'].includes(get(employer, 'statutory_parameters.region', null));

HOURLY_MINIMUM_WAGE.condition:
// Decree 74/2024/ND-CP on regional hourly minimum wages Art.3(1) (23,800/21,200/18,600/16,600 VND/h): trigger condition.
const rate = get(ctx.entry, 'terms.rate', null);
return rate !== null && ['HOURLY', 'DAILY'].includes(rate.unit);

HOURLY_MINIMUM_WAGE.validate:
const employer = ctx.subject.employer;
const region = get(employer, 'statutory_parameters.region', null);
const floor = get(ctx.lookup.hourly_by_region, region, null);
if (floor === null) return true;
const rate = ctx.entry.terms.rate;
if (rate.unit === 'HOURLY') return rate.amount >= floor;
// A day converts to an hour over the normal hours of the day, or to a month over the normal days; either floor met is enough (art.4(3)).
const hours = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
if (!(hours > 0)) return false;
if (rate.amount / hours >= floor) return true;
const days = Number(get(ctx.entry, 'terms.normal_days_per_week', 0));
return (rate.amount * days * 52) / 12 >= get(ctx.lookup.minimum_wage.by_region, region, Infinity);

PROBATION_WAGE.condition:
// Labour Code arts.26, 90(2): check every probation monthly contract
const rate = get(ctx.entry, 'terms.rate', null);
if (get(ctx.entry, 'terms.probation_period', null) === null) return false;
return rate !== null && rate.unit === 'MONTHLY';

PROBATION_WAGE.validate:
// Labour Code arts.26, 90(2): probation wage >= 85% of a compliant (>= regional minimum wage) job wage
const region = get(ctx.subject.employer, 'statutory_parameters.region', null);
const floor = Number(get(ctx.lookup.minimum_wage.by_region, region, 0));
const job = get(ctx.entry, 'statutory_parameters.probation_job_wage_vnd', null);
if (job != null && floor > 0 && Number(job) < floor) return false;
const base = job != null ? Math.max(Number(job), floor) : floor;
return base <= 0 || Number(ctx.entry.terms.rate.amount) >= ctx.lookup.share * base;

PROBATION_PERIOD.condition:
// Labour Code 45/2019/QH14 art.25: Checks the probation length against the statutory maximum for the job class.
const period = get(ctx.entry, 'terms.probation_period', null);
if (period === null) return false;
if (period.to === null) return false;
return get(ctx.entry, 'statutory_parameters.probation_class', null) !== null;

PROBATION_PERIOD.validate:
// Labour Code 45/2019/QH14 art.25: Checks the probation length against the statutory maximum for the job class.
const period = ctx.entry.terms.probation_period;
const jobClass = get(ctx.entry, 'statutory_parameters.probation_class', null);
if (jobClass === 'OTHER')
	return period.to <= add_working_days(period.from, ctx.lookup.other_working_days - 1, [], [6, 0]);
const days = calendar_distance_days(period.from, period.to) + 1;
if (jobClass === 'ENTERPRISE_MANAGER') return days <= ctx.lookup.enterprise_manager_days;
if (jobClass === 'COLLEGE_OR_ABOVE') return days <= ctx.lookup.college_days;
return days <= ctx.lookup.intermediate_days;

PREGNANT_OR_INFANT_NIGHT_OVERTIME.validate:
// Labour Code art.137(1): pregnancy (a) has no consent exception; an infant under 12 months (b) needs the day's consent.
const contract = ctx.subject.employment;
const date = ctx.entry.work_date;
const consent = get(ctx.entry, 'consent', {});
const children = get(contract, 'family', []).filter((member) => member.relation === 'CHILD');
const pregnant = children.some((child) => {
	const due = get(child, 'expected_on', null);
	const born = get(child, 'born_on', null);
	return due !== null && born === null && date >= add_months(due, -ctx.lookup.advance_months);
});
const night = clock_window_minutes(
	get(ctx.entry, 'actual_worked_intervals', []) ?? [],
	"Asia/Ho_Chi_Minh",
	ctx.lookup.night_from,
	ctx.lookup.night_to
);
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
if (pregnant) return night === 0 && overtime === 0;
const infant = children.some((child) => {
	const born = get(child, 'born_on', null);
	return born !== null && add_months(born, ctx.lookup.infant_months) > date;
});
if (!infant) return true;
return (
	(night === 0 || get(consent, 'night_work', false) === true) &&
	(overtime === 0 || get(consent, 'overtime', false) === true)
);

MINOR_WORKING_TIME.validate:
// Labour Code 45/2019/QH14 art.146(1)(b): compliance validation.
const contract = ctx.subject.employment;
const dob = get(contract, 'payroll.date_of_birth', null);
if (dob === null) return true;
const age = age_on(dob, ctx.entry.work_date);
if (age >= ctx.lookup.young_age) return true;
const worked = interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []) / 60;
const week = ctx.reads.roster_entry.filter(
	(day) => day.work_date !== ctx.entry.work_date && day.work_date >= add_days(ctx.entry.work_date, -6)
);
const weekly =
	(sum(week.map((day) => interval_minutes(day.actual_worked_intervals ?? []))) +
		interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? [])) /
	60;
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
const night = clock_window_minutes(
	get(ctx.entry, 'actual_worked_intervals', []) ?? [],
	"Asia/Ho_Chi_Minh",
	ctx.lookup.night_from,
	ctx.lookup.night_to
);
if (age < ctx.lookup.child_age) {
	if (!(worked <= ctx.lookup.child_daily)) return false;
	if (!(weekly <= ctx.lookup.child_weekly)) return false;
	return overtime === 0 && night === 0;
}
const listed = get(contract, 'statutory_parameters.minor_listed_job', false) === true;
if (!(worked <= ctx.lookup.young_daily)) return false;
if (!(weekly <= ctx.lookup.young_weekly)) return false;
if (listed) return true;
return overtime === 0 && night === 0;

WEEKLY_REST.validate:
// Labour Code 45/2019/QH14 art.111(1): compliance validation.
const on = String(ctx.entry.work_date);
const employer = ctx.subject.employer;
if (get(employer, 'statutory_parameters.rest_averaged_monthly', false) === true) {
	const from = month_start(on);
	const to = month_end(on);
	const siblings = ctx.reads.roster_entry.filter(
		(day) => day.work_date >= from && day.work_date <= to && day.work_date !== on
	);
	const rest = siblings.filter(
		(day) => interval_minutes(day.actual_worked_intervals ?? []) === 0
	).length;
	return siblings.length + 1 < ctx.lookup.month_records || rest >= ctx.lookup.rest_days;
}
const from = add_days(on, -(ctx.lookup.worked_days - 1));
const siblings = ctx.reads.roster_entry.filter(
	(day) => day.work_date >= from && day.work_date < on
);
const worked =
	siblings.filter((day) => interval_minutes(day.actual_worked_intervals ?? []) > 0).length + 1;
return siblings.length < ctx.lookup.worked_days - 1 || worked < ctx.lookup.worked_days;

ROSTER_NORMAL_HOURS_DAY.validate:
// Labour Code 2019 art.105(1)–(2): compliance validation.
const contract = ctx.subject.employment;
const agreed = get(contract, 'terms.normal_hours_per_day', ctx.lookup.daily_hours);
const cap = agreed > ctx.lookup.daily_hours ? ctx.lookup.weekly_arrangement_hours : ctx.lookup.daily_hours;
const worked = interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []) / 60;
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []) / 60;
return worked - overtime <= cap;

ROSTER_NORMAL_HOURS_WEEK.validate:
// Labour Code 2019 art.105(1)–(2): Checks that normal hours actually worked across the seven-day window stay within 48 hours.
const from = add_days(ctx.entry.work_date, -6);
const siblings = ctx.reads.roster_entry.filter(
	(day) => day.work_date >= from && day.work_date <= ctx.entry.work_date && day.work_date !== ctx.entry.work_date
);
const worked =
	sum(siblings.map((day) => interval_minutes(day.actual_worked_intervals ?? []))) +
	interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []);
const overtime =
	sum(siblings.map((day) => interval_minutes(day.planned_overtime_intervals ?? []))) +
	interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
return (worked - overtime) / 60 <= ctx.lookup.weekly_hours;

ROSTER_OVERTIME_DAY.validate:
// Labour Code 2019 art.107(2)(b): compliance validation.
const contract = ctx.subject.employment;
const normal = Number(get(contract, 'terms.normal_hours_per_day', 0));
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []) / 60;
if (!(normal > 0)) return false;
if (!(overtime <= ctx.lookup.share * normal)) return false;
return normal + overtime <= ctx.lookup.daily_hours;

ROSTER_SHIFT_CHANGE_REST.validate:
// Labour Code 2019 art.110: compliance validation.
const previous = ctx.reads.roster_entry
	.filter((day) => day.work_date < ctx.entry.work_date && interval_minutes(day.actual_worked_intervals ?? []) > 0)
	.toSorted((left, right) => (left.work_date < right.work_date ? 1 : -1))[0];
if (previous === undefined) return true;
const intervals = previous.actual_worked_intervals ?? [];
const last = intervals[intervals.length - 1];
const end = get(last, 'end', null);
const firstInterval = get(ctx.entry, 'actual_worked_intervals', [])[0];
if (end === null) return true;
return elapsed_minutes(end, firstInterval.start) / 60 >= ctx.lookup.rest_hours;

ROSTER_MINOR_WORKING_TIME.validate:
// Labour Code 2019 art.146: compliance validation.
const contract = ctx.subject.employment;
const dob = get(contract, 'payroll.date_of_birth', null);
if (dob === null) return true;
const age = age_on(dob, ctx.entry.work_date);
if (age >= ctx.lookup.young_age) return true;
const listed = get(contract, 'statutory_parameters.minor_listed_job', false) === true;
if (age >= ctx.lookup.child_age && listed) return true;
return false;

ROSTER_MATERNITY_NIGHT_OVERTIME.validate:
// Labour Code art.137(1): pregnancy (a) has no consent exception; an infant under 12 months (b) needs the day's consent.
const contract = ctx.subject.employment;
const date = ctx.entry.work_date;
const consent = get(ctx.entry, 'consent', {});
const children = get(contract, 'family', []).filter((member) => member.relation === 'CHILD');
const pregnant = children.some((child) => {
	const due = get(child, 'expected_on', null);
	const born = get(child, 'born_on', null);
	return due !== null && born === null && date >= add_months(due, -ctx.lookup.advance_months);
});
if (pregnant) return false;
const infant = children.some((child) => {
	const born = get(child, 'born_on', null);
	return born !== null && add_months(born, ctx.lookup.infant_months) > date;
});
if (!infant) return true;
return get(consent, 'overtime', false) === true;

ROSTER_UNDER_13.validate:
// Labour Code 2019 art.145(3): compliance validation.
const contract = ctx.subject.employment;
const dob = get(contract, 'payroll.date_of_birth', null);
if (dob === null) return true;
if (age_on(dob, ctx.entry.work_date) >= ctx.lookup.age_years) return true;
return get(contract, 'statutory_parameters.child_arts_sports_approved', false) === true;

ENCASHMENT_PRIOR_WAGE_REVIEW.validate:
// Labour Code art.113(3); Decree 145/2020 art.67(3): encashment permitted only on exit and priced at prior-month daily wage
const contract = ctx.subject.employment;
const exit = get(contract, 'effective_range.to', null);
if (exit == null) return false;
const review = get(contract, 'statutory_parameters.encashment_review', null);
return (
	review !== null &&
	get(review, 'month', '') === add_months(month_start(exit), -1).substring(0, 7) &&
	Number(get(review, 'daily_wage_vnd', 0)) > 0
);

ANNUAL_SERVICE_EXIT_REVIEW.validate:
// Decree 145/2020/ND-CP arts.65-66: compliance validation.
const exit = ctx.entry.effective_range.to;
const review = get(ctx.entry, 'statutory_parameters.annual_leave_service_review', null);
if (review === null) return false;
if (String(get(review, 'year', '')) !== exit.substring(0, 4) || get(review, 'as_of', '') !== exit) return false;
const covered = ctx.reads.workplace_case_catalog_entry.some((record) => {
	if (!(record.opened_on <= exit)) return false;
	if (record.closed_on != null && !(record.closed_on >= exit)) return false;
	if (!(get(record, 'inputs.effective_from', '') <= exit)) return false;
	return get(record, 'inputs.effective_to', '') >= exit;
});
if (!covered) return true;
if (get(review, 'carry_previous_year_days', null) === null) return false;
return get(review, 'carry_second_previous_year_days', null) !== null;

CONTRACT_CATEGORIES.validate:
// Labour Code; Decree 219/2025; Decree 393/2026: validate residency, work category & work_authorisation_category
const residency = get(ctx.entry, 'terms.residency_status', null);
const category = get(ctx.entry, 'terms.statutory_work_category', null);
const pass = get(ctx.entry, 'terms.work_authorisation_category', null);
if (residency === null) return false;
if (!ctx.lookup.residency_status.includes(residency)) return false;
if (category !== null && !ctx.lookup.work_classification.includes(category)) return false;
return pass === null || ctx.lookup.work_pass_categories.includes(pass);

SHARED_STRUCTURED_EMPLOYEE_INPUTS.validate:
// Labour Code 45/2019/QH14; Law 41/2024; PIT Law Statutory parameters: Checks the bounds on structured employee inputs such as normal hours and normal days.
return Object.keys(ctx.lookup.bounds).every((path) => {
	const value = get(ctx.entry, path, null);
	const bound = ctx.lookup.bounds[path];
	if (value === null) return get(bound, 'required', false) !== true;
	const minimum = get(bound, 'minimum', null);
	const maximum = get(bound, 'maximum', null);
	const allowed = get(bound, 'allowed', null);
	if (minimum !== null && value < minimum) return false;
	if (maximum !== null && value > maximum) return false;
	if (allowed !== null && !allowed.includes(value)) return false;
	return true;
});

SHARED_ORIGINAL_AGREEMENT_INTENT.validate:
// Labour Code 45/2019/QH14, article20: Checks that the signed contract period is a real fixed term within the 36-month maximum.
const agreement = get(ctx.entry, 'signed_contract_period', null);
if (agreement === null) return false;
if (agreement.to === null) return true;
return (
	agreement.to >= agreement.from &&
	add_days(agreement.to, 1) <= add_months(agreement.from, ctx.lookup.maximum_fixed_term_months)
);

OPERATIONS_EVENT_DATE_REQUIRED.validate:
// Labour Code 45/2019/QH14 art.99: Requires a company with a first-employment date to record the date operations started.
const firstEmployed = get(ctx.entry, 'statutory_parameters.first_employed_on', null);
if (firstEmployed === null) return true;
return get(ctx.entry, 'statutory_parameters.operations_started_on', null) !== null;

BUSINESS_CASE_SUBJECT_AND_REFERENCE.validate:
// Labour Code 45/2019/QH14; PDPL 91/2025 Subject & reference: Requires an annual-leave combining agreement to name its employment and carry a reference.
const reference = get(ctx.entry, 'reference', null);
return (
	get(ctx.entry, 'employment_id', null) !== null &&
	typeof reference === 'string' &&
	reference.trim() !== ''
);

BUSINESS_CASE_EFFECTIVE_INTERVAL.validate:
