// Decree 393/2026, effective 5 December 2026 arts9(8),17(1),21(3),29(1),30,35: Raises the task to record the work-authorisation route and the number of extensions used.
const today = String(get(first(ctx.reads.payroll_run), 'pay_date', ''));
const key = 'WORK_AUTHORISATION_EXPIRY_INPUTS_393:' + ctx.entry.employment_id;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
return [
	{
		entity_id: ctx.entry.entity_id,
		employee_id: ctx.entry.employee_id,
		employment_id: ctx.entry.employment_id,
		title: ctx.lookup.title,
		due_on: today,
		occurrence_key: key
	}
];

WORK_PERMIT_RETURN.condition:
// Decree 219/2025/NĐ-CP arts.30(1), 31(1): Raises the task to return a work authorisation with its invalidation report on termination.
if (ctx.after == null) return false;
if (get(ctx.entry, 'terms.work_authorisation_category', null) !== 'PERMIT') return false;
if (!(ctx.entry.effective_range.to >= ctx.lookup.commencement)) return false;
const invalidatedOn = get(ctx.entry.statutory_parameters, 'work_authorisation_invalidated_on', null);
const ground = get(ctx.entry.statutory_parameters, 'work_authorisation_invalidation_ground', null);
return invalidatedOn == null || ground == null;

WORK_PERMIT_RETURN.effects:
// Decree 219/2025/NĐ-CP arts.30(1), 31(1): Raises the task to return a work authorisation with its invalidation report on termination.
const key = 'WORK_AUTHORISATION_RETURN:' + ctx.entry.id + ':exit:' + ctx.entry.effective_range.to;
if (get(ctx, 'reads.obligation', []).some((o) => o.occurrence_key === key)) return [];
return [
	{
		entity_id: ctx.entry.entity_id,
		employee_id: ctx.entry.employee_id,
		employment_id: ctx.entry.id,
		title: ctx.lookup.title,
		due_on: add_working_days(ctx.entry.effective_range.to, ctx.lookup.working_days, get(ctx, 'reads.holiday', []).map((h) => h.date), [0, 6]),
		occurrence_key: key
	}
];

MINIMUM_WAGE_FLOOR.validate:
// Labour Code 45/2019/QH14 arts.90(2), 91 art.3(1), art.5(1)–(3): compliance validation.
const employer = ctx.subject.employer;
const region = get(employer, 'statutory_parameters.region', null);
const floor = get(ctx.lookup.minimum_wage.by_region, region, null);
return floor === null || ctx.entry.terms.rate.amount >= floor;
